// #1981 Collections photos: real Wikimedia Commons photos (free licence), WebP, served from this site (public/collections).
// collections-images.json is the manifest (author, licence, source URL per image); generated by cloud-me's data/regen-geo-images-1981.py --fetch.
import manifest from './collections-images.json';

export interface ImageCredit { title: string; author: string; license: string; license_url: string; source_url: string }

const IMAGES = (manifest as unknown as { images: Record<string, ImageCredit> }).images;

/** The two generic slides that follow a collection's own photo in its overlay. */
export const GENERIC_SLIDES = ['travel', 'landscape'];

export const thumbUrl = (key: string): string => `collections/${key}-t.webp`;
export const heroUrl = (key: string): string => `collections/${key}.webp`;
export const creditOf = (key: string): ImageCredit | undefined => IMAGES[key];
